971	/** Read `df` free bytes for a path (GNU `--output`, with a portable fallback). */
972	async function availBytes(conn: Client, path: string): Promise<number | null> {
973	  const r = await sh(conn, `df -B1 --output=avail ${path} 2>/dev/null | tail -n1`);
974	  let n = Number(clean(r.stdout, 32));
975	  if (!Number.isFinite(n) || n <= 0) {
976	    const r2 = await sh(conn, `df -B1 ${path} 2>/dev/null | awk 'NR==2{print $4}'`);
977	    n = Number(clean(r2.stdout, 32));
978	  }
979	  return Number.isFinite(n) && n > 0 ? n : null;
980	}
