982	/** Parse `lsblk -b -P` KEY="value" output into rows. */
983	function parseLsblk(out: string): BlockDev[] {
984	  const rows: BlockDev[] = [];
985	  for (const line of (out ?? "").split("\n")) {
986	    if (!line.trim()) continue;
987	    const kv: Record<string, string> = {};
988	    for (const m of line.matchAll(/([A-Z]+)="([^"]*)"/g)) kv[m[1]] = m[2];
989	    if (!kv.NAME) continue;
990	    rows.push({
991	      name: clean(kv.NAME, 64),
992	      type: clean(kv.TYPE ?? "", 32),
993	      sizeBytes: Number(kv.SIZE) || 0,
994	      fstype: clean(kv.FSTYPE ?? "", 32),
995	      mount: clean(kv.MOUNTPOINT ?? kv.MOUNTPOINTS ?? "", 255),
996	    });
997	  }
998	  return rows;
999	}
