1001	/**
1002	 * Find a block device on the TARGET that is attached but completely unused —
1003	 * TYPE=disk, no filesystem, no mountpoint, no partitions and not the disk that
1004	 * carries `/`. A real migration had a 20 GB volume sitting idle in exactly this
1005	 * state while the root disk filled to 92% and the builds died.
1006	 *
1007	 * The name is validated against BLOCKDEV_RE and is additionally re-confirmed
1008	 * blank with `blkid` (must FAIL, i.e. no signature at all) immediately before
1009	 * anything is written — we will never mkfs a device that has any content.
1010	 */
1011	async function findUnusedDisk(conn: Client): Promise<BlockDev | null> {
1012	  const ls = await sh(conn, `lsblk -b -P -o NAME,TYPE,SIZE,FSTYPE,MOUNTPOINT 2>/dev/null`);
1013	  if (ls.code !== 0) return null;
1014	  const rows = parseLsblk(ls.stdout);
1015	  if (!rows.length) return null;
1016	
1017	  // Belt and braces: never touch the disk that backs `/`.
1018	  let rootDisk = "";
1019	  const rs = await sh(conn, `findmnt -n -o SOURCE / 2>/dev/null | head -n1`);
1020	  const rootSrc = clean(rs.stdout, 128);
1021	  if (/^\/dev\/[A-Za-z0-9/_-]{1,64}$/.test(rootSrc)) {
1022	    const pk = await sh(conn, `lsblk -no PKNAME ${rootSrc} 2>/dev/null | head -n1`);
1023	    const d = clean(pk.stdout, 64);
1024	    if (BLOCKDEV_RE.test(d)) rootDisk = d;
1025	  }
1026	
1027	  const candidates = rows.filter(
1028	    (d) =>
1029	      d.type === "disk" &&
1030	      !d.fstype &&
1031	      !d.mount &&
1032	      d.name !== rootDisk &&
1033	      BLOCKDEV_RE.test(d.name) &&
1034	      d.sizeBytes >= MIN_EXTRA_DISK_BYTES &&
1035	      // no partitions / LVM / crypt children carved out of it
1036	      !rows.some((o) => o.name !== d.name && o.name.startsWith(d.name))
1037	  );
1038	  if (!candidates.length) return null;
1039	  candidates.sort((a, b) => b.sizeBytes - a.sizeBytes);
1040	  const pick = candidates[0];
1041	
1042	  // Final confirmation that the device really is blank before we consider it.
1043	  const blk = await sh(conn, `blkid /dev/${pick.name} >/dev/null 2>&1; echo $?`);
1044	  if (clean(blk.stdout, 8) === "0") return null; // has a signature — hands off
1045	  const inUse = await shOk(conn, `findmnt -S /dev/${pick.name} >/dev/null 2>&1`);
1046	  if (inUse) return null;
1047	  return pick;
1048	}
