1050	/** Format + persistently mount a blank disk at EXTRA_DISK_MOUNT. Idempotent. */
1051	async function prepareExtraDisk(conn: Client, dev: string): Promise<{ ok: boolean; detail: string }> {
1052	  if (!BLOCKDEV_RE.test(dev)) return { ok: false, detail: "device name failed validation" };
1053	  const mk = await sh(conn, `mkfs.ext4 -F -m 0 -L nxeon-data /dev/${dev} 2>&1`, INSTALL_TIMEOUT_MS);
1054	  if (mk.code !== 0) return { ok: false, detail: `mkfs.ext4 failed: ${tailOf(mk)}` };
1055	
1056	  const bl = await sh(conn, `blkid -s UUID -o value /dev/${dev} 2>/dev/null`);
1057	  const uuid = clean(bl.stdout, 64);
1058	  if (!UUID_RE.test(uuid)) return { ok: false, detail: "could not read a valid filesystem UUID" };
1059	
1060	  await sh(conn, `mkdir -p ${EXTRA_DISK_MOUNT}`);
1061	  // Persist by UUID so it survives a reboot; `nofail` keeps a detached volume
1062	  // from wedging the boot. Idempotent — the grep guard makes a re-run a no-op.
1063	  await sh(
1064	    conn,
1065	    `grep -q "UUID=${uuid} " /etc/fstab || printf 'UUID=%s %s ext4 defaults,nofail 0 2\\n' '${uuid}' '${EXTRA_DISK_MOUNT}' >> /etc/fstab`
1066	  );
1067	  const mnt = await sh(conn, `mountpoint -q ${EXTRA_DISK_MOUNT} || mount ${EXTRA_DISK_MOUNT} 2>&1 || mount /dev/${dev} ${EXTRA_DISK_MOUNT} 2>&1`, SETUP_TIMEOUT_MS);
1068	  const mounted = await shOk(conn, `mountpoint -q ${EXTRA_DISK_MOUNT}`);
1069	  if (!mounted) return { ok: false, detail: `mount failed: ${tailOf(mnt)}` };
1070	  return { ok: true, detail: `formatted ext4 and mounted at ${EXTRA_DISK_MOUNT} (fstab UUID entry added)` };
1071	}
