1073	/**
1074	 * Move Docker's on-disk state onto the extra volume BEFORE anything is pulled,
1075	 * loaded or built.
1076	 *
1077	 * BOTH stores are relocated. `/var/lib/containerd` is a SEPARATE store from
1078	 * `/var/lib/docker`: with the containerd image store that `get.docker.com`
1079	 * installs on Ubuntu 22.04, image layers and build ingest
1080	 * (`io.containerd.content.v1.content/ingest/…`) live under containerd. In the
1081	 * field, relocating only `/var/lib/docker` still let the root disk reach 100%
1082	 * with 9.4 GB parked in `/var/lib/containerd`. Bind mounts are used for both, so
1083	 * one mechanism covers both stores regardless of which image store is active and
1084	 * without rewriting a daemon.json we do not own.
1085	 *
1086	 * Safety: the daemons are stopped first, data is rsynced (not moved) and the old
1087	 * directory is only deleted after the bind mount is CONFIRMED live.
1088	 */
1089	async function relocateDockerStores(
1090	  conn: Client,
1091	  say: (line: string) => Promise<void>
1092	): Promise<{ moved: string[]; failed: string[] }> {
1093	  const moved: string[] = [];
1094	  const failed: string[] = [];
1095	  await sh(conn, `systemctl stop docker.socket docker containerd 2>/dev/null; true`, SETUP_TIMEOUT_MS);
1096	
1097	  for (const store of DOCKER_STORES) {
1098	    const leaf = store.slice(store.lastIndexOf("/") + 1);
1099	    const dest = `${EXTRA_DISK_MOUNT}/${leaf}`;
1100	    // Already relocated (a re-run, or the previous attempt got this far)?
1101	    const already = await sh(conn, `findmnt -n -o SOURCE --target ${store} 2>/dev/null`);
1102	    if (clean(already.stdout, 255).startsWith(EXTRA_DISK_MOUNT)) {
1103	      moved.push(`${store} (already on ${EXTRA_DISK_MOUNT})`);
1104	      continue;
1105	    }
1106	    await sh(conn, `mkdir -p ${dest} ${store}`);
1107	    const cp = await sh(conn, `rsync -a --numeric-ids ${store}/ ${dest}/ 2>&1`, TRANSFER_TIMEOUT_MS);
1108	    if (cp.code !== 0) {
1109	      failed.push(`${store}: copy failed (${tailOf(cp)})`);
1110	      continue;
1111	    }
1112	    await sh(
1113	      conn,
1114	      `grep -q " ${store} none bind" /etc/fstab || printf '%s %s none bind,nofail 0 0\\n' '${dest}' '${store}' >> /etc/fstab`
1115	    );
1116	    // Empty the original only AFTER the copy succeeded, and keep it aside until
1117	    // the bind mount is confirmed.
1118	    await sh(conn, `rm -rf ${store}.premigrate && mv ${store} ${store}.premigrate && mkdir -p ${store}`, SETUP_TIMEOUT_MS);
1119	    const mnt = await sh(conn, `mount --bind ${dest} ${store} 2>&1`, SETUP_TIMEOUT_MS);
1120	    const live = await shOk(conn, `mountpoint -q ${store}`);
1121	    if (!live) {
1122	      // Roll back cleanly — better a full root disk than a broken Docker.
1123	      await sh(conn, `rmdir ${store} 2>/dev/null; mv ${store}.premigrate ${store} 2>/dev/null; true`);
1124	      await sh(conn, `sed -i '\\| ${store} none bind|d' /etc/fstab 2>/dev/null; true`);
1125	      failed.push(`${store}: bind mount failed (${tailOf(mnt)}) — left in place`);
1126	      continue;
1127	    }
1128	    await sh(conn, `rm -rf ${store}.premigrate 2>/dev/null; true`, SETUP_TIMEOUT_MS);
1129	    moved.push(store);
1130	  }
1131	
1132	  await sh(conn, `systemctl enable --now containerd 2>/dev/null; systemctl enable --now docker 2>/dev/null; true`, INSTALL_TIMEOUT_MS);
1133	  const df = await sh(conn, `df -h ${DOCKER_STORES.join(" ")} 2>/dev/null | tail -n +2`);
1134	  const dfTail = clean(df.stdout, 400).split("\n").map((l) => l.trim()).filter(Boolean).join(" | ");
1135	  if (dfTail) await say(`  Docker storage now: ${dfTail}`);
1136	  return { moved, failed };
1137	}
