563	      }
564	    : null;
565	
566	  if (SANDBOX) {
567	    // Synthetic 80 GB disk with ~63 GB free, matching our default plan sizing.
568	    return {
569	      info: {
570	        disk: { totalBytes: 80 * GiB, usedBytes: 17 * GiB, availBytes: 63 * GiB },
571	        os: osFallback ?? { id: "ubuntu", versionId: "24.04", pretty: "Ubuntu 24.04 LTS" },
572	        arch: "x86_64",
573	      },
574	    };
575	  }
576	
577	  // Need dedicatedIp to compute the SSH connection target (dedicated → :22).
578	  const full = await db.server.findUnique({
579	    where: { id: server.id },
580	    include: { dedicatedIp: true },
