604	      // Largest attached-but-unformatted disk (an unused volume). A disk counts
605	      // as blank only when neither it nor any child has a filesystem or mount.
606	      let spareDiskBytes: number | null = null;
607	      try {
608	        const lb = await exec(
609	          conn,
610	          "for d in $(lsblk -dn -o NAME,TYPE 2>/dev/null | awk '$2==\"disk\"{print $1}'); do " +
611	            "if [ -z \"$(lsblk -n -o FSTYPE,MOUNTPOINT /dev/$d 2>/dev/null | tr -d ' \\n')\" ]; then " +
612	            "lsblk -bdn -o SIZE /dev/$d 2>/dev/null; fi; done",
613	          QUICK_TIMEOUT_MS
614	        );
615	        const sizes = ((lb.stdout as string) || "")
616	          .split("\n")
617	          .map((s) => Number(s.trim()))
618	          .filter((n) => Number.isFinite(n) && n > 0);
619	        if (sizes.length) spareDiskBytes = Math.max(...sizes);
620	      } catch {
621	        /* best-effort: absence just means we report root-only free space */
622	      }
623	      return { disk, os, arch: arch ?? "x86_64", spareDiskBytes };
624	    });
625	    return { info };
626	  } catch {
627	    // Unreachable / probe error → soft warning (no hard block).
628	    return { info: { disk: null, os: osFallback, arch: "x86_64" } };
629	  }
630	}
