/**
 * Find EVERY block device on the TARGET that is attached but completely unused.
 * A disk qualifies ONLY if all of these hold — the bar is deliberately absolute,
 * because the cost of getting it wrong is destroying a customer's data:
 *
 *   • TYPE=disk (a whole device, never a partition/LVM/crypt node),
 *   • no FSTYPE on the device itself,
 *   • no partitions or children of ANY kind carved out of it,
 *   • no mountpoint anywhere in its tree (walked via PKNAME, so an LVM or
 *     dm-crypt stack rooted on the disk still disqualifies it),
 *   • it is not the disk carrying the root filesystem,
 *   • `blkid` finds NO signature at all on it,
 *   • nothing in /sys/block/<dev>/holders is using it,
 *   • it is at least MIN_EXTRA_DISK_BYTES.
 *
 * A real migration had a 20 GB volume sitting idle in exactly this state while
 * the root disk filled to 92% and the builds died; another had 20 GB + 30 GB
 * attached and was refused because 34.5 GB fitted on neither disk alone. Hence
 * the plural: the caller pools everything this returns.
 *
 * Returned largest-first. Every name has passed BLOCKDEV_RE, so it is safe to
 * interpolate into a command.
 */
async function findUnusedDisks(conn: Client): Promise<BlockDev[]> {
  const ls = await sh(conn, `lsblk -b -P -o NAME,TYPE,SIZE,FSTYPE,MOUNTPOINT,PKNAME 2>/dev/null`);
  if (ls.code !== 0) return [];
  const rows = parseLsblk(ls.stdout);
  if (!rows.length) return [];

  const byName = new Map(rows.map((r) => [r.name, r]));
  /** Walk PKNAME up to the top-level device (bounded — never trust a cycle). */
  const topOf = (name: string): string => {
    let cur = name;
    for (let i = 0; i < 8; i++) {
      const row = byName.get(cur);
      if (!row?.pkname || row.pkname === cur) break;
      cur = row.pkname;
    }
    return cur;
  };

