      d.sizeBytes >= MIN_EXTRA_DISK_BYTES &&
      // no partitions / LVM / crypt children carved out of it
      !rows.some((o) => o.name !== d.name && (o.pkname === d.name || topOf(o.name) === d.name))
  );
  if (!candidates.length) return [];

  // Final per-device confirmation, immediately before the caller writes anything.
  const blank: BlockDev[] = [];
  for (const c of candidates) if (await verifyBlank(conn, c.name)) blank.push(c);
  blank.sort((a, b) => b.sizeBytes - a.sizeBytes);
  return blank;
}

/**
 * Re-confirm, in ONE round trip, that a device is untouched: no blkid signature
 * of any kind, not mounted, no device-mapper/md holder, no children. Every check
 * must come back negative — anything ambiguous means "hands off".
 */
async function verifyBlank(conn: Client, name: string): Promise<boolean> {
  if (!BLOCKDEV_RE.test(name)) return false;
  const r = await sh(
    conn,
    `blkid /dev/${name} >/dev/null 2>&1 && echo SIG; ` +
      `findmnt -S /dev/${name} >/dev/null 2>&1 && echo MOUNTED; ` +
      `[ -n "$(ls -A /sys/block/${name}/holders 2>/dev/null)" ] && echo HELD; ` +
      `[ -n "$(lsblk -no NAME /dev/${name} 2>/dev/null | tail -n +2)" ] && echo CHILD; ` +
      `echo READY`
  );
  const out = clean(r.stdout, 256);
  return out.includes("READY") && !/SIG|MOUNTED|HELD|CHILD/.test(out);
}

/**
 * Persist an ALREADY-FORMATTED filesystem at EXTRA_DISK_MOUNT: fstab entry by
 * UUID (never by device name — an added volume can come back as a different
 * /dev/sdX) with `nofail` so a missing disk cannot wedge the boot, then mount.
 * Idempotent: the grep guard and the `mountpoint -q` short-circuit make a re-run
 * a no-op. NEVER formats — the caller owns that decision.
 */
async function mountExtraFs(conn: Client, devPath: string): Promise<{ ok: boolean; detail: string }> {
  if (!DEVPATH_RE.test(devPath)) return { ok: false, detail: "device path failed validation" };
  const bl = await sh(conn, `blkid -s UUID -o value ${devPath} 2>/dev/null`);
  const uuid = clean(bl.stdout, 64);
  if (!UUID_RE.test(uuid)) return { ok: false, detail: "could not read a valid filesystem UUID" };

  await sh(conn, `mkdir -p ${EXTRA_DISK_MOUNT}`);
  await sh(
    conn,
    `grep -q "UUID=${uuid} " /etc/fstab || printf 'UUID=%s %s ext4 defaults,nofail 0 2\\n' '${uuid}' '${EXTRA_DISK_MOUNT}' >> /etc/fstab`
  );
  const mnt = await sh(
    conn,
    `mountpoint -q ${EXTRA_DISK_MOUNT} || mount ${EXTRA_DISK_MOUNT} 2>&1 || mount ${devPath} ${EXTRA_DISK_MOUNT} 2>&1`,
    SETUP_TIMEOUT_MS
  );
  const mounted = await shOk(conn, `mountpoint -q ${EXTRA_DISK_MOUNT}`);
  if (!mounted) return { ok: false, detail: `mount failed: ${tailOf(mnt)}` };
  return { ok: true, detail: `mounted at ${EXTRA_DISK_MOUNT} (fstab UUID entry, nofail)` };
}

/** Format + persistently mount ONE blank disk at EXTRA_DISK_MOUNT. Idempotent. */
async function prepareExtraDisk(conn: Client, dev: string): Promise<{ ok: boolean; detail: string }> {
  if (!BLOCKDEV_RE.test(dev)) return { ok: false, detail: "device name failed validation" };
  const mk = await sh(conn, `mkfs.ext4 -F -m 0 -L nxeon-data /dev/${dev} 2>&1`, INSTALL_TIMEOUT_MS);
  if (mk.code !== 0) return { ok: false, detail: `mkfs.ext4 failed: ${tailOf(mk)}` };
  const m = await mountExtraFs(conn, `/dev/${dev}`);
  if (!m.ok) return m;
  return { ok: true, detail: `formatted ext4 and ${m.detail}` };
}

/**
 * Adopt a `nxeondata` pool left by a previous run instead of rebuilding it.
 *
 *   null              → no such volume group; the caller may create one.
 *   { ok: true, … }   → activated, filesystem present, mounted. NOT reformatted.
 *   { ok: false, … }  → the VG exists but is not usable (no LV, or no filesystem
 *                       on the LV). We refuse to touch it — recreating would
 *                       destroy whatever it holds — and say so.
 */
async function adoptExistingPool(
  conn: Client
): Promise<{ ok: boolean; detail: string; disks: string[]; bytes: number } | null> {
  if (!(await shOk(conn, `command -v vgs >/dev/null 2>&1`))) return null;
  const vg = await sh(conn, `vgs --noheadings -o vg_name 2>/dev/null | tr -d ' ' | grep -x ${POOL_VG}`);
  if (vg.code !== 0) return null;

  await sh(conn, `vgchange -ay ${POOL_VG} >/dev/null 2>&1; true`, SETUP_TIMEOUT_MS);
  const lv = await sh(conn, `lvs --noheadings -o lv_name ${POOL_VG} 2>/dev/null | tr -d ' ' | grep -x ${POOL_LV}`);
  if (lv.code !== 0) {
    return {
      ok: false,
      detail: `a '${POOL_VG}' volume group already exists but has no '${POOL_LV}' volume — leaving it untouched rather than risking its contents`,
      disks: [],
      bytes: 0,
    };
  }
  const fs = await sh(conn, `blkid -s TYPE -o value ${POOL_LV_PATH} 2>/dev/null`);
  if (!/^ext[234]$/.test(clean(fs.stdout, 16))) {
    return {
      ok: false,
      detail: `'${POOL_VG}/${POOL_LV}' already exists but carries no ext4 filesystem — leaving it untouched rather than reformatting it`,
      disks: [],
      bytes: 0,
    };
  }

  const pv = await sh(
    conn,
    `pvs --noheadings -o pv_name,vg_name 2>/dev/null | awk '$2=="${POOL_VG}"{print $1}'`
  );
  const disks = clean(pv.stdout.replace(/\n/g, " "), 512)
    .split(/\s+/)
    .map((p) => p.replace(/^\/dev\//, ""))
    .filter((n) => BLOCKDEV_RE.test(n));
  const sz = await sh(conn, `blockdev --getsize64 ${POOL_LV_PATH} 2>/dev/null`);
  const bytes = Number(clean(sz.stdout, 24)) || 0;

  const m = await mountExtraFs(conn, POOL_LV_PATH);
  if (!m.ok) return { ok: false, detail: `existing ${POOL_VG} pool could not be mounted: ${m.detail}`, disks, bytes };
  return {
    ok: true,
    detail:
      `reused the existing ${human(bytes)} storage pool '${POOL_VG}'` +
      (disks.length ? ` across ${disks.length} volume(s) (${disks.map((d) => `/dev/${d}`).join(" + ")})` : "") +
      ` — ${m.detail}, nothing reformatted`,
    disks,
    bytes,
  };
}

/**
 * Build ONE ext4 filesystem spanning 2+ blank disks via LVM, so their capacity
 * actually adds up. Every device name has already passed BLOCKDEV_RE and
 * verifyBlank; the VG/LV names are compile-time constants.
 *
 * On ANY failure the partial state we created is torn back down (lvremove →
 * vgremove → pvremove → wipefs) so the disks return to the blank state we found
 * them in and the caller's single-disk fallback can still use them. A failed
 * pool must never leave the target worse off than before.
 */
async function createDiskPool(
  conn: Client,
  disks: BlockDev[],
  say: (line: string) => Promise<void>
): Promise<{ ok: boolean; detail: string; disks: string[]; bytes: number }> {
  const names = disks.map((d) => d.name);
  if (!names.length || names.some((n) => !BLOCKDEV_RE.test(n))) {
    return { ok: false, detail: "device name failed validation", disks: [], bytes: 0 };
  }
  const devs = names.map((n) => `/dev/${n}`).join(" ");
  const rawTotal = disks.reduce((n, d) => n + d.sizeBytes, 0);
  await say(`  Combining ${names.length} blank volumes (${devs.replace(/ /g, " + ")}, ${human(rawTotal)} raw) into one LVM pool.`);

  let touchedPvs = false;
  let madeVg = false;
  let madeLv = false;
  const undo = async (why: string) => {
    if (madeLv) await sh(conn, `lvremove -f ${POOL_VG}/${POOL_LV} >/dev/null 2>&1; true`, SETUP_TIMEOUT_MS);
    if (madeVg) await sh(conn, `vgremove -f ${POOL_VG} >/dev/null 2>&1; true`, SETUP_TIMEOUT_MS);
    if (touchedPvs) {
      // Only ever run against devices confirmed signature-free moments ago and
      // written to by THIS function — this removes our own PV headers, nothing else.
      await sh(conn, `pvremove -ff -y ${devs} >/dev/null 2>&1; true`, SETUP_TIMEOUT_MS);
      await sh(conn, `wipefs -a ${devs} >/dev/null 2>&1; true`, SETUP_TIMEOUT_MS);
    }
    await say(`  Rolled the half-built pool back — the volumes are blank again (${why}).`);
  };

  // `</dev/null` so an unexpected LVM confirmation prompt ABORTS instead of
  // hanging (and instead of us blanket-answering "yes" to a wipe).
  touchedPvs = true;
  const pv = await sh(conn, `pvcreate ${devs} </dev/null 2>&1`, SETUP_TIMEOUT_MS);
  if (pv.code !== 0) {
    await undo("pvcreate");
    return { ok: false, detail: `pvcreate failed: ${tailOf(pv)}`, disks: [], bytes: 0 };
  }
  const vg = await sh(conn, `vgcreate ${POOL_VG} ${devs} </dev/null 2>&1`, SETUP_TIMEOUT_MS);
  if (vg.code !== 0) {
    await undo("vgcreate");
    return { ok: false, detail: `vgcreate failed: ${tailOf(vg)}`, disks: [], bytes: 0 };
  }
  madeVg = true;
  const lv = await sh(conn, `lvcreate -l 100%FREE -n ${POOL_LV} ${POOL_VG} </dev/null 2>&1`, SETUP_TIMEOUT_MS);
  if (lv.code !== 0) {
    await undo("lvcreate");
    return { ok: false, detail: `lvcreate failed: ${tailOf(lv)}`, disks: [], bytes: 0 };
  }
  madeLv = true;
  const mk = await sh(conn, `mkfs.ext4 -F -m 0 -L nxeon-data ${POOL_LV_PATH} 2>&1`, INSTALL_TIMEOUT_MS);
  if (mk.code !== 0) {
    await undo("mkfs.ext4");
    return { ok: false, detail: `mkfs.ext4 on the pool failed: ${tailOf(mk)}`, disks: [], bytes: 0 };
  }

  const m = await mountExtraFs(conn, POOL_LV_PATH);
  if (!m.ok) {
    await undo("mount");
    return { ok: false, detail: `pool built but ${m.detail}`, disks: [], bytes: 0 };
  }
  // Make sure the VG is activated on every boot (udev does this on Debian/Ubuntu;
  // the monitor unit is belt and braces). Best-effort — the mount has `nofail`.
  await sh(conn, `systemctl enable --now lvm2-monitor >/dev/null 2>&1; vgchange -ay ${POOL_VG} >/dev/null 2>&1; true`, SETUP_TIMEOUT_MS);

  const sz = await sh(conn, `blockdev --getsize64 ${POOL_LV_PATH} 2>/dev/null`);
  const bytes = Number(clean(sz.stdout, 24)) || rawTotal;
  return {
    ok: true,
    detail:
      `${names.length} volumes (${names.map((n) => `/dev/${n}`).join(" + ")}) pooled into one ` +
      `${human(bytes)} ext4 filesystem — ${m.detail}`,
    disks: names,
    bytes,
  };
}

/**
 * Turn whatever blank volumes are attached into ONE usable filesystem at
 * EXTRA_DISK_MOUNT, and say honestly what was done.
 *
 *   0 disks → nothing (the caller keeps everything on root)
 *   1 disk  → today's simple path: mkfs.ext4 straight onto the disk. No LVM
 *             where it isn't needed.
 *   2+      → install lvm2, then pool them. If ANY step fails, roll back and
 *             fall back to the single largest disk (re-verified blank first);
 *             if that is impossible too, report why and leave the target exactly
 *             as it was.
 *
 * A pool from an earlier run is always adopted, never recreated or reformatted.
 */
async function prepareExtraStorage(
  conn: Client,
  disks: BlockDev[],
  say: (line: string) => Promise<void>
): Promise<{ ok: boolean; detail: string; pooled: boolean; disks: string[]; bytes: number }> {
  const usable = disks.filter((d) => BLOCKDEV_RE.test(d.name));

  // 0) Re-runs and retries: an existing pool wins outright.
  const existing = await adoptExistingPool(conn);
  let poolingBlocked = "";
  if (existing?.ok) return { ...existing, pooled: true };
  if (existing) {
    poolingBlocked = existing.detail;
    await say(`  ${existing.detail}.`);
  }

  if (!usable.length) {
    return {
      ok: false,
      detail: poolingBlocked || "no blank volume is available to use",
      pooled: false,
      disks: [],
      bytes: 0,
    };
  }

  const single = async (why: string) => {
    const largest = [...usable].sort((a, b) => b.sizeBytes - a.sizeBytes)[0];
    if (!(await verifyBlank(conn, largest.name))) {
      return {
        ok: false,
        detail: `${why}, and /dev/${largest.name} is no longer confirmed blank — nothing was changed`,
        pooled: false,
        disks: [],
        bytes: 0,
      };
    }
    const r = await prepareExtraDisk(conn, largest.name);
    return {
      ok: r.ok,
      detail: usable.length > 1 ? `${why} — used /dev/${largest.name} on its own instead: ${r.detail}` : `/dev/${largest.name}: ${r.detail}`,
      pooled: false,
      disks: r.ok ? [largest.name] : [],
      bytes: r.ok ? largest.sizeBytes : 0,
    };
  };

  // 1) One disk (or pooling is off the table) → the simple, proven path.
  if (usable.length === 1) return single("single unused volume");
  if (poolingBlocked) return single(`could not pool: ${poolingBlocked}`);

  // 2) Two or more → pool them.
  const pkg = await ensurePackages(conn, ["lvm2"]);
  if (!pkg[0]?.ok) return single(`could not install lvm2 (${pkg[0]?.err ?? "unknown error"})`);

  const pool = await createDiskPool(conn, usable, say);
  if (pool.ok) {
    await say(`  ${POOL_DETACH_WARNING}`);
    return { ...pool, pooled: true };
  }
  return single(`pooling failed (${pool.detail})`);
}
