  /**
   * Capacity of the LARGEST attached-but-unformatted block device (an added
   * volume the customer hasn't used yet), or null if there isn't one. The engine
   * formats it and relocates the container stores onto it, so this space is
   * genuinely available to the migration — without it the wizard reports only
   * the root filesystem and tells the customer a move "won't fit" that the
   * engine would happily run. Largest (not the sum): separate disks are separate
   * filesystems and the engine uses one, so they do not pool.
   */
  spareDiskBytes?: number | null;
};

// Largest attached-but-unformatted disk (an unused volume). A disk counts
// as blank only when neither it nor any child has a filesystem or mount.
let spareDiskBytes: number | null = null;
try {
  const lb = await exec(
    conn,
    "for d in $(lsblk -dn -o NAME,TYPE 2>/dev/null | awk '$2==\"disk\"{print $1}'); do " +
      "if [ -z \"$(lsblk -n -o FSTYPE,MOUNTPOINT /dev/$d 2>/dev/null | tr -d ' \\n')\" ]; then " +
      "lsblk -bdn -o SIZE /dev/$d 2>/dev/null; fi; done",
    QUICK_TIMEOUT_MS
  );
  const sizes = ((lb.stdout as string) || "")
    .split("\n")
    .map((s) => Number(s.trim()))
    .filter((n) => Number.isFinite(n) && n > 0);
  if (sizes.length) spareDiskBytes = Math.max(...sizes);
} catch {
  /* best-effort: absence just means we report root-only free space */
}
return { disk, os, arch: arch ?? "x86_64", spareDiskBytes };

