// Every attached-but-unformatted disk (unused volumes the customer added).
// Read-only probe, and it mirrors the engine's qualification bar exactly so
// the panel can never promise space the engine would refuse to touch: a
// disk counts only when nothing in its tree has a filesystem or mount, it
// has no children, nothing holds it, `blkid` finds no signature at all,
// and it is at least the engine's 4 GiB floor.
let spareDiskBytes: number | null = null;
let spareDiskCount: number | null = null;
try {
  const lb = await exec(
    conn,
    "for d in $(lsblk -dn -o NAME,TYPE 2>/dev/null | awk '$2==\"disk\"{print $1}'); do " +
      "[ -n \"$(lsblk -n -o FSTYPE,MOUNTPOINT /dev/$d 2>/dev/null | tr -d ' \\n')\" ] && continue; " +
      "[ -n \"$(lsblk -no NAME /dev/$d 2>/dev/null | tail -n +2)\" ] && continue; " +
      "[ -n \"$(ls -A /sys/block/$d/holders 2>/dev/null)\" ] && continue; " +
      "blkid /dev/$d >/dev/null 2>&1 && continue; " +
      "sz=$(lsblk -bdn -o SIZE /dev/$d 2>/dev/null | tr -d ' '); " +
      "[ -z \"$sz\" ] && continue; " +
      "[ \"$sz\" -ge 4294967296 ] 2>/dev/null && echo \"$sz\"; done",
    QUICK_TIMEOUT_MS
  );
  const sizes = ((lb.stdout as string) || "")
    .split("\n")
    .map((s) => Number(s.trim()))
    .filter((n) => Number.isFinite(n) && n > 0);
  if (sizes.length) {
    // The poolable total. 2+ blank volumes are combined into ONE filesystem
    // by the engine (LVM volume group + a single ext4 on top), so their
    // capacity genuinely adds up; one volume is simply its own size.
    spareDiskCount = sizes.length;
    spareDiskBytes = sizes.reduce((a, b) => a + b, 0);
  }
} catch {
  /* best-effort: absence just means we report root-only free space */
}
return { disk, os, arch: arch ?? "x86_64", spareDiskBytes, spareDiskCount };

