// LVM pooling. Two attached volumes are two filesystems — they do NOT pool by
// themselves, and a real customer with 20 GB + 30 GB attached still had the
// migration refused because 34.5 GB of Docker images fitted on neither disk on
// its own. With 2+ blank disks we build ONE volume group across all of them and
// put a single ext4 on top, so the customer gets the combined capacity.
// Every name here is a compile-time constant — nothing source-supplied ever
// reaches an LVM command; only BLOCKDEV_RE-validated device names are appended.
const POOL_VG = "nxeondata";
const POOL_LV = "data";
const POOL_LV_PATH = `/dev/${POOL_VG}/${POOL_LV}`;
/**
 * The honest cost of pooling, surfaced in the log AND in the final summary.
 * A linear VG spans its PVs: the filesystem's data is spread across every disk,
 * so detaching ANY one volume destroys the whole pool, not just that disk's
 * share. The customer has to know this before they go and detach a volume from
 * the panel six months later.
 */
const POOL_DETACH_WARNING =
  "IMPORTANT: these volumes are now combined into ONE storage pool. " +
  "Detaching or deleting ANY of them destroys the entire pool and everything on it " +
  `(${DOCKER_STORES.join(" + ")}). Keep all of them attached, or move the data off first.`;

